-- 168_school_intro_backfill_round1.sql
-- 院校简介回填（第 168 批，2026-11-24）：为 12 所「官网可查、简介为空」的普通高校回填简介。
--
-- 口径：
--   * 只取院校官网「学校简介 / 学校概况」页自述原文，逐字摘录，不改写、不拼接他校内容；
--   * 每条约 200-500 字，只在句末标点（。；）处截断，不切半句；
--   * 仅当库内 intro 为空时更新，重复执行不覆盖既有简介；不物理删除。
--
-- 证据逐条留痕（id / 院校 / 简介页 URL）：
--   backfill_local/out/school_intro_168_evidence.csv
--
-- 本轮未处理（下轮候选，原因随附）：
--   #163 山西大同大学：官网 www.sxdtdx.edu.cn 的「学校概况」页 403/无法访问（http/https 均失败）；
--   #591 汕头大学 / #711 云南农业大学 / #745 西安美术学院 / #789 兰州城市学院 /
--   #842 衡水学院 / #1035 成都工业学院 / #1065 甘肃民族师范学院：官网首页为 JS 壳或改版跳转，正文抓不到；
--   #641 海南医科大学 / #653 西南政法大学 / #860 太原学院 / #1006 长沙工业学院 /
--   #1039 成都师范学院 / #1062 陕西学前师范学院：简介页为 JS/iframe 渲染或栏目列表，抓不到正文；
--   #926 浙江音乐学院 / #844 邯郸学院 / #830 北京联合大学：官网无独立简介页，
--     首页仅有新闻流/宣传段落，非完整简介，暂不采用；
--   #715 云南中医药大学 / #722 玉溪师范学院：简介页自带「…」截断，正文不足 200 字，留待补全；
--   #897 黑龙江工业学院 / #1034 成都大学：官网当前不可达。

UPDATE kaoyan_schools AS s
SET intro = v.intro,
    updated_at = now()
FROM (VALUES
    (250, '佳木斯大学是中国最东端的高等学府，是国家百所“中西部高校基础能力建设工程”支持高校，是黑龙江省唯一设有医学学科的综合性大学，是黑龙江省重点建设的高水平大学。学校坐落于华夏东极、全国最佳魅力生态城市，有着“东北小延安”美誉之称的佳木斯市。佳木斯市位于三江平原流域，拥有世界三大湿地之一的三江湿地、享誉中外的黑瞎子岛和独具特色的赫哲风情，是北大荒精神的主要发源地，是国家重要的商品粮食生产基地，是中国最早迎接太阳升起的地方。学校始建于1947年7月20日，1995年经原国家教委批准，由佳木斯医学院、佳木斯工学院、佳木斯师范专科学校及原佳木斯大学（市属）合并组建。2000年后，佳木斯市粮食职工中等专业学校、富锦师范学校、黑龙江省理工学校相继并入。学校在佳木斯市有五个校区，校园占地面积128.71万平方米，总占地面积240.68万平方米。主校区南偎四丰山，北揽松花江，处处绿意盎然，景致如画，获评省级文明校园和全省首批“绿色校园”。医学新校区聚力打造医工融合实践载体，建设医学人才培养与科研平台，为医学学科高质量发展夯基赋能。'),
    (402, '皖西学院是经教育部批准设立的省属综合性公办本科高校，办学历史可以追溯到全国人大常委会原副委员长、全国政协原副主席、民革中央原主席朱蕴山先生1918年创办的“安徽省立第三甲种农业学校”。学校坐落在历史文化悠久、红色底蕴深厚的大别山区域中心城市——六安市。学校是硕士学位授予单位、安徽省地方应用型高水平大学建设单位、安徽省应用特色高校建设单位；获批第一批全国依法治校示范校、人力资源社会保障部“国家级专家服务基地”、安徽省课程思政建设先行高校、安徽省第一届文明校园。学校位于风景秀丽的月亮岛上，被誉为“最美岛上大学”。校园占地1765亩，总建筑面积57.6万平方米。设有15个二级学院，66个本科专业，拥有电子信息、中药2个硕士学位授权点。现有国家级一流专业建设点2个，国家级特色专业2个，国家级专业综合改革试点专业1个；省级一流专业14个，省级双特色专业2个，省级“六卓越一拔尖”计划专业18个，省级现代产业学院3个。现有全日制在校本科生近22000人，研究生211人；在职教职工近1300人，其中高级专业技术职称385人，具有博士学位的教师432人。'),
    (535, '武汉音乐学院是我国中部地区唯一独立设置的高等音乐学府。1953年11月19日，由中南文艺学院、华南人民文学艺术学院和广西省立艺术专科学校之音乐部分组建而成的中南音乐专科学校，是武汉音乐学院的建校起点。中南文艺学院的前身包括私立武昌艺术专科学校（1930）、湖南省立音乐专科学校（1947）、中原大学文艺学院（1949）；华南人民文学艺术学院的前身有广东省立艺术专科学校（1940）、广州市立艺术专科学校（1947）和香港中华音乐院（1947）；广西省立艺术专科学校的前身是广西省会国民基础学校艺术师资训练班（1938），她们共同构成了武汉音乐学院丰富多样、积淀深厚的音乐教育历史传承。1958年，中南音乐专科学校与华中师范学院音乐系、美术系及湖北群众艺术干部学校合并，组建湖北艺术学院。1985年，改建定名为武汉音乐学院。学校是全国首批硕士学位授予单位，是湖北省首批重点学科建设单位，是湖北省首批国内一流学科建设高校，音乐与舞蹈学是湖北省首批国内一流学科建设学科。有艺术学、马克思主义理论（思想政治教育）学科，音乐、舞蹈专业学位类别4个硕士学位授权点。'),
    (600, '惠州学院地处全国文明城市、国家历史文化名城、粤港澳大湾区重要节点城市——惠州，是省属全日制公办本科高校、硕士学位授予单位、全国新建本科院校联盟副理事长单位、普通本科转型试点高校和省创建国家教师教育创新实验区立项院校、省高校“三全育人”体制机制建设试点单位、省课程思政改革示范高校。学校前身为1946年创办的广东省立惠州师范学校，1978年升格为惠阳师范专科学校，2000年升格为全日制普通本科院校，2024年成为硕士学位授予单位。学校秉承“敦重明辨、求真致用”校训，努力建设理工科特色鲜明、教师教育协调发展的高水平应用型大学，培养具有科学精神、人文素养、国际视野、创新思维的高素质应用型人才，是东江流域重要的人才摇篮。学校占地约2422亩，馆藏图书（含电子文献）达262万册(件)，面向20多个省（自治区、直辖市）招生，全日制在校生达2.4万人，现有专任教师1001名，其中高级职称324人；博士547名，博士占比54.65%；省优秀教学团队、高校创新团队39个。学校坚持走国际化办学道路，同美、英、日等10个国家和港澳台地区超过30所高校、研究所、企业、专业团体开展各类交流与合作。'),
    (608, '学校前身是1925年由近代民主革命先驱何香凝先生等提议、为纪念伟大的爱国主义者廖仲恺先生爱护农工的意愿而决定创办的“仲恺农工学校”。1927年3月，学校正式招生，初设蚕丝科和农科，何香凝先生亲任校长。1980年，学校被确定为全国重点中等专业学校。1984年，经教育部、农牧渔业部批准，学校升格为本科院校，定名“仲恺农业技术学院”，国家副主席王震同志题写校名。2006年1月获得硕士学位授予权。2008年3月，经教育部批准，更名“仲恺农业工程学院”。2021年获批为博士学位授权立项建设单位。学校的建设和发展备受各级领导和社会各界的高度重视与鼎力支持。党和国家领导人叶剑英、邓小平、杨尚昆、王震先后为校园内的廖仲恺何香凝纪念馆、廖仲恺铜像、何香凝汉白玉塑像和廖仲恺纪念碑题字；杨尚昆、李希、康克清、廖承志、何鲁丽、周铁农、万鄂湘、廖晖、霍英东、马万祺、齐续春、郑建邦等多次亲临学校视察指导工作。1987年4月，根据国家副主席王震提议，经中共广东省委同意，成立了学校董事会，王震任名誉董事长，时任广东省省长叶选平任董事长，董事会成员由国家领导人、省部级领导以及港澳知名人士等担任。'),
    (632, '广西民族大学地处广西首府南宁，是国家民族事务委员会和广西壮族自治区人民政府共建高校。学校创建于1952年3月，前身是中央民族学院（今中央民族大学）广西分院，1953年2月更名为广西省民族学院，1958年6月更名为广西民族学院，2006年2月更名为广西民族大学。学校占地面积3600亩，现有相思湖、思源湖和武鸣三个校区，校园环境优美静谧，建筑风格古朴典雅，人文氛围深厚浓郁，是读书治学的理想园地。现有教学科研仪器设备共7.2万余台（件），价值6.38亿元，图书馆馆藏纸质资源总量282.82万册，电子图书610.61万册，电子期刊412.42万册，电子版学位论文2311.78万篇，音视频153.17万小时。现有教职工2584人，专任教师1985人，博士学位教师849人。拥有国家“万人计划”哲学社会科学领军人才、茅盾文学奖获得者、鲁迅文学奖获得者、享受国务院政府特殊津贴专家、全国优秀教师、全国模范教师、中宣部文化名家暨“四个一批”人才、教育部“新世纪优秀人才支持计划”人才、广西八桂学者等国家级、省部级人才百余人次。拥有教育部“全国高校黄大年式教师团队”1个。'),
    (679, '攀枝花学院是教育部布点在川西南、滇西北唯一一所以工为主的综合性普通本科院校。学校因国家“三线建设”战略而生，因服务区域发展而兴，坐落于著名的钒钛之都、阳光花城、康养胜地、全国唯一以花命名的城市——攀枝花市市区，是一所具有深厚三线历史文化底蕴和鲜明办学特色的地方应用型本科院校。学校由方毅、宋任穷等老一辈革命家倡导，始建于1983年，党和国家领导人方毅、费孝通先后题写“攀枝花大学”“攀枝花学院”校名。1995年升格为普通高等专科学校，2001年升格为本科院校并更名为“攀枝花学院”，2005年获得学士学位授予权，2007年开始联合培养研究生，2017年开始举办留学生教育，2021年获批成为硕士学位授予单位，2025年获批四川省人民政府学位委员会博士学位授予立项建设单位（重点培养类）。'),
    (880, '辽东学院地处鸭绿江畔、黄海之滨，坐落在抗美援朝出征地——辽宁省丹东市。作为辽东地区公办本科院校，多年来，学校扎根边疆，全面履行“国门大学”使命，致力于建设特色鲜明的高水平应用型大学。学校高等教育始于1948年创建的安东省立农业专科学校。此后数十年间，丹东地区先后涌现了农业、师范、财经、纺织、医学等十余所高等学校。经过不断改革发展建设，2003年4月，经教育部批准，辽宁财政高等专科学校与丹东职业技术学院合并组建辽东学院，彻底改变了辽东地区没有本科高校的历史。学校有临江、金山两个主要校区，校园总面积82万多平方米，建筑面积41万平方米，固定资产总值8亿元，图书馆藏书119.7万余册。“知行并重、致用为本”办学理念，践行“明德笃学、践履惟新”的校训精神，构建了高水平应用型人才培养体系，是辽宁省唯一承担农村订单定向医学生免费培养项目和乡村医生委托定向培养项目的高校。'),
    (896, '哈尔滨金融学院坐落于国家历史文化名城、享有“亚欧大陆桥的明珠”美誉的城市——哈尔滨市，学校由中国人民银行创办，是一所传承“央行基因”，扎根龙江，立足金融办教育的应用型本科财经大学。办学历史源远流长，文化底蕴深厚。学校始建于1950年，历经东北银行黑龙江省分行干部培训班、中国人民银行齐齐哈尔干部学校、黑龙江银行学校、哈尔滨金融专科学校、哈尔滨金融高等专科学校等几个历史时期，是经国务院批准组建的我国第一所金融类高等专科学校，原隶属于中国人民银行总行，2000年全国高等学校管理体制改革后，改为中央和地方共建，以地方管理为主。2010年4月，经教育部批准，升格为哈尔滨金融学院。经过全体师生共同努力，学校已顺利通过教育部本科教学工作合格评估，成功获批硕士学位授予立项建设单位。办学条件优良，满足教育发展需求。学校现占地面积65.89万平方米，校舍建筑面积29.96万平方米。电子资源649万余册，已初步形成文献种类齐全、金融特色突出的馆藏资源体系。升级改造140间多媒体教室，实现全覆盖，建有48个各类实验室、5间智慧教室、7间语音室、87个校外实习基地，实践教学条件达到国内同类院校一流水平。'),
    (1020, '百色学院是2006年教育部批准成立的普通本科高校，源于1938年成立的广西省立田西师范学校，历经广西省立百色师范学校、广西省立百色南武联合师范学校、百色师范专科学校、百色地区师范学校、右江民族师范专科学校、右江民族师范高等专科学校等阶段；其间，广西省立南武师范学校、省立天保师范学校、县立田阳简易师范、百色民族师范学校、百色民族中专学校先后并入。坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻党的教育方针，落实立德树人根本任务，围绕建设特色鲜明、多学科协同发展的区域性高水平应用型大学办学定位，秉承“志远行敏，德高业精”的校训，弘扬“团结合作、艰苦奋斗、克难攻坚、磨砺成才”石磨文化，形成“革命性、民族性、边疆性、区域性、开放性、生态性”办学思路，实施红色铸魂“三全育人”体系和“双元制+双园制”应用型人才培养体系“双系驱动”育人模式”，突显“红色铸魂、学以致用”办学特色，培养德智体美劳全面发展的高水平应用型人才。'),
    (1048, '昭通学院是一所省属公办普通本科高校，其师范教育传统可追溯到1906年清政府创设的师范传习所，历经省立第二师范学校、昭通地区师范学校，1978年成立昭通师范专科学校，1992年更名为昭通师范高等专科学校，1999年与昭通教育学院、云南电大昭通分校合并，2000年与昭通地区师范学校合并。2012年升格为本科院校，校名为昭通学院；2021年通过教育部本科教学工作合格评估；2022年列入教育部师范教育协同提质计划重点支持院校；2023年列入云南省教育厅和昭通市人民政府共建高校；2024年列入硕士学位授予单位及硕士点培育省级立项建设名单。百年积淀，熔炼形成了“大学无疆，大人有容”的校训和“崇德、敬业、务实、创新”的校风。夯基垒台，积厚成势。昭通学院占地面积71.5万㎡，建筑面积为26.3万㎡，教学科研仪器设备总值近1.54亿元。图书馆建筑面积2.6万㎡，收藏纸质图书102.75万册、电子图书154.72万册。'),
    (1051, '楚雄师范学院位于云南省楚雄彝族自治州楚雄市，是一所具有90年师范教育积淀，教师教育特色鲜明，多学科协调发展的省属本科高校。学校办学历史可追溯于1936年建校的省立镇南师范学校。1953年更名为楚雄师范学校，1984年更名为楚雄民族师范学校。1978年，经云南省计委批准，学校开设“楚雄师专班”，1992年更名为楚雄师范高等专科学校。1999年楚雄民族师范学校并入楚雄师范高等专科学校。2001年5月，经教育部批准，由楚雄师范高等专科学校升格为本科层次的楚雄师范学院。')
) AS v(id, intro)
WHERE s.id = v.id
  AND (s.intro IS NULL OR btrim(s.intro) = '');
